package pl.medivalrpg.ludnosc.template;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.YamlConfiguration;

/**
 * Player-facing texts of the built-in templates ({@code opisy.yml} in the jar, generated by
 * {@code templates-src/generate.py}): the full description (what the building does, what it needs, its look) and the
 * short effect for the list of {@code /ludnosc typy}.
 *
 * <p>A template file in {@code plugins/Ludnosc/budynki/} overrides the built-in of the same id — also a copy exported
 * by an older version, which would keep its old description for ever. So the text shown for a built-in id is the
 * current one from the jar unless the file carries a description that was never shipped (an admin wrote it): that one
 * is kept. Templates that are not built-in (schematics, own YAML files, player copies) keep their own description and
 * have no short effect. Immutable, pure; safe from any thread.</p>
 */
public final class TemplateTexts {

    /** Texts of one built-in template. */
    public record Entry(String base, String effect, String description, String look, List<String> previous) {
    }

    public static final String RESOURCE = "opisy.yml";

    private final Map<String, Entry> entries;

    public TemplateTexts(final Map<String, Entry> entries) {
        this.entries = Map.copyOf(entries);
    }

    /** Reads {@code opisy.yml} from the class path. */
    public static TemplateTexts load() throws IOException {
        try (InputStream in = TemplateTexts.class.getClassLoader().getResourceAsStream(RESOURCE)) {
            if (in == null) {
                throw new IOException("Brak zasobu " + RESOURCE);
            }
            try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8)) {
                return parse(YamlConfiguration.loadConfiguration(reader));
            }
        }
    }

    public static TemplateTexts parse(final ConfigurationSection yaml) {
        final Map<String, Entry> out = new HashMap<>();
        for (final String id : yaml.getKeys(false)) {
            final ConfigurationSection s = yaml.getConfigurationSection(id);
            if (s != null) {
                out.put(id, new Entry(s.getString("base", id), s.getString("effect", ""), s.getString("description", ""),
                    s.getString("look", ""), List.copyOf(s.getStringList("previous"))));
            }
        }
        return new TemplateTexts(out);
    }

    public static TemplateTexts empty() {
        return new TemplateTexts(Map.of());
    }

    public Entry entry(final String id) {
        return id == null ? null : this.entries.get(id);
    }

    public Map<String, Entry> entries() {
        return this.entries;
    }

    /** The template's own description is one we shipped (now or before) or missing, i.e. nobody rewrote it. */
    private static boolean shipped(final Entry e, final String own) {
        return own == null || own.isBlank() || own.equals(e.description()) || e.previous().contains(own);
    }

    /** Description to show for a template (see the class comment). */
    public String description(final BuildingTemplate t) {
        final Entry e = this.entries.get(t.id());
        final String own = t.meta().description();
        return e != null && shipped(e, own) ? e.description() : own;
    }

    /** Short effect for the list ("podatki +8%"), empty for templates that are not built-in or were re-described. */
    public String effect(final BuildingTemplate t) {
        final Entry e = this.entries.get(t.id());
        return e != null && shipped(e, t.meta().description()) ? e.effect() : "";
    }
}
